def _new_game_with_two_players():
    game = Game()
    p1 = game.add_player("Alice")
    p2 = game.add_player("Bob")
    return game, p1, p2


def _create_in_hand(game, player, name):
    """Create the card in the player's HAND without firing interceptor setup."""
    cdef = FINAL_FANTASY_CARDS[name]
    obj = game.create_object(
        name=name,
        owner_id=player.id,
        zone=ZoneType.HAND,
        characteristics=cdef.characteristics,
        card_def=None,  # delay setup until ZONE_CHANGE -> battlefield
    )
    obj.card_def = cdef
    return obj


def _move_to_battlefield(game, obj, player):
    """Move HAND -> BATTLEFIELD via ZONE_CHANGE so setup_interceptors + ETB fire."""
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': f'hand_{player.id}',
            'to_zone': 'battlefield',
            'to_zone_type': ZoneType.BATTLEFIELD,
        }
    ))


def _make_dummy_target(game, player):
    from src.engine import make_creature, Color
    cdef = make_creature(
        name="Dummy Target", power=2, toughness=2,
        mana_cost="{1}{G}", colors={Color.GREEN},
        subtypes={"Beast"}, text="",
    )
    return game.create_object(
        name="Dummy Target", owner_id=player.id,
        zone=ZoneType.BATTLEFIELD,
        characteristics=cdef.characteristics, card_def=cdef,
    )


def _make_dummy_spell(game, player):
    """Create a generic instant card on the stack (we just need a CAST source)."""
    from src.cards.card_factories import make_instant
    from src.engine import Color
    cdef = make_instant(name="Dummy Spell", mana_cost="{1}", colors={Color.BLUE}, text="")
    return game.create_object(
        name="Dummy Spell", owner_id=player.id,
        zone=ZoneType.STACK,
        characteristics=cdef.characteristics, card_def=cdef,
    )


def _seed_board(game, p1, p2):
    """Seed both players with dummy permanents + lands + graveyard cards."""
    from src.engine import make_creature, Color
    _make_dummy_target(game, p1)
    _make_dummy_target(game, p2)
    # Graveyards
    for pid in (p1.id, p2.id):
        gy_key = f"graveyard_{pid}"
        if gy_key not in game.state.zones:
            from src.engine.types import Zone
            game.state.zones[gy_key] = Zone(id=gy_key, zone_type=ZoneType.GRAVEYARD)
        cdef = make_creature(
            name="Dummy GY Beast", power=2, toughness=2,
            mana_cost="{1}{G}", colors={Color.GREEN},
            subtypes={"Beast"}, text="",
        )
        game.create_object(
            name="Dummy GY Beast", owner_id=pid,
            zone=ZoneType.GRAVEYARD,
            characteristics=cdef.characteristics, card_def=cdef,
        )
    # Lands so triggers that read "untapped lands" or "lands you control" fire
    from src.cards.card_factories import make_land
    for _ in range(3):
        land = make_land(name="Dummy Land", text="")
        game.create_object(
            name="Dummy Land", owner_id=p1.id,
            zone=ZoneType.BATTLEFIELD,
            characteristics=land.characteristics, card_def=land,
        )
        land2 = make_land(name="Dummy Land 2", text="")
        game.create_object(
            name="Dummy Land 2", owner_id=p2.id,
            zone=ZoneType.BATTLEFIELD,
            characteristics=land2.characteristics, card_def=land2,
        )


def _collect_event_types(game, since_idx: int) -> set:
    log = getattr(game.state, 'event_log', None)
    if log is None:
        log = getattr(game, 'event_log', []) or []
    return {ev.type for ev in log[since_idx:]}


def _event_log_len(game) -> int:
    log = getattr(game.state, 'event_log', None)
    if log is None:
        log = getattr(game, 'event_log', []) or []
    return len(log)


EQUIVALENT = {
    EventType.EXILE: {EventType.ZONE_CHANGE, EventType.EXILE_FROM_TOP, EventType.EXILE_TOP, EventType.EXILE_TOP_CARD},
    EventType.RETURN_TO_HAND: {EventType.ZONE_CHANGE, EventType.BOUNCE},
    EventType.OBJECT_DESTROYED: {EventType.DESTROY, EventType.ZONE_CHANGE},
    EventType.SACRIFICE: {EventType.OBJECT_DESTROYED, EventType.ZONE_CHANGE},
    EventType.DRAW: set(),
    EventType.DISCARD: {EventType.ZONE_CHANGE},
    EventType.MILL: {EventType.ZONE_CHANGE},
    EventType.OBJECT_CREATED: {EventType.CREATE_TOKEN},
    EventType.LIFE_CHANGE: {EventType.LIFE_GAIN, EventType.LIFE_LOSS},
    EventType.PT_MODIFICATION: {EventType.TEMPORARY_EFFECT, EventType.PUMP, EventType.GRANT_PT_MODIFIER, EventType.PT_MODIFIER, EventType.PT_CHANGE, EventType.PT_MODIFY, EventType.TEMPORARY_BOOST},
    EventType.TEMPORARY_EFFECT: {EventType.GRANT_KEYWORD, EventType.KEYWORD_GRANT, EventType.GRANT_ABILITY, EventType.PT_MODIFICATION, EventType.PUMP},
    EventType.TAP_TARGET: {EventType.TAP},
    EventType.UNTAP_TARGET: {EventType.UNTAP},
    EventType.DAMAGE: set(),
    EventType.COUNTER: {EventType.COUNTER_SPELL, EventType.SPELL_COUNTERED},
    EventType.COUNTER_ADDED: set(),
    EventType.COPY_SPELL: {EventType.COPY_STACK_ITEM},
    EventType.MANA_ADDED: set(),
}


def _expand_expected(expected_set):
    out = set(expected_set)
    for e in list(expected_set):
        out |= EQUIVALENT.get(e, set())
    return out


def _assert_expected_event_emitted(game, since_idx, expected_set, card_name, trigger_kind):
    emitted = _collect_event_types(game, since_idx)
    bookkeeping = {
        EventType.TRIGGERED_ABILITY_PUT_ON_STACK,
        EventType.PHASE_START, EventType.PHASE_END, EventType.PHASE_CHANGE,
        EventType.PRIORITY_PASS,
    }
    effective = emitted - bookkeeping
    if not effective:
        expected_names = sorted(e.name for e in expected_set)
        emitted_names = sorted(e.name for e in emitted)
        raise AssertionError(
            f"{card_name}: {trigger_kind} fired but produced ZERO effect events "
            f"(depths trap). Emitted only bookkeeping: {emitted_names}. "
            f"Expected one of: {expected_names}"
        )
    if not expected_set:
        return
    expanded = _expand_expected(expected_set)
    overlap = effective & expanded
    if not overlap:
        emitted_names = sorted(e.name for e in emitted)
        expected_names = sorted(e.name for e in expected_set)
        raise AssertionError(
            f"{card_name}: {trigger_kind} emitted {emitted_names} "
            f"but expected at least one of {expected_names}"
        )


def test_a_vivi_ornitier():
    '''A-Vivi Ornitier: spell-cast trigger emits one of ['COUNTER_ADDED', 'DAMAGE'].'''
    game, p1, p2 = _new_game_with_two_players()
    _seed_board(game, p1, p2)
    card = _create_in_hand(game, p1, 'A-Vivi Ornitier')
    _move_to_battlefield(game, card, p1)
    # cast something - emit a CAST event
    before = _event_log_len(game)
    spell = _make_dummy_spell(game, p1)
    game.emit(Event(
        type=EventType.CAST,
        payload={'object_id': spell.id, 'controller': p1.id, 'player': p1.id},
    ))
    _assert_expected_event_emitted(game, before, {EventType.COUNTER_ADDED, EventType.DAMAGE}, 'A-Vivi Ornitier', 'spell_cast')

