if __name__ == "__main__":
    import traceback
    test_fns = [v for k, v in list(globals().items()) if k.startswith("test_") and callable(v)]
    passed, failed, errors = [], [], []
    for t in test_fns:
        try:
            t()
            passed.append(t.__name__)
        except AssertionError as e:
            failed.append((t.__name__, str(e)[:300]))
        except Exception as e:
            errors.append((t.__name__, f"{type(e).__name__}: {str(e)[:300]}"))
    print(f"\n=== Interceptor verification: Final Fantasy (FIN) ===")
    print(f"  passed:  {len(passed)}")
    print(f"  failed:  {len(failed)}")
    print(f"  errors:  {len(errors)}")
    print(f"  skipped: {len(SKIPPED_CARDS)} (see SKIPPED_CARDS dict)")
    total = len(test_fns)
    if total:
        rate = 100.0 * len(passed) / total
        print(f"  pass rate: {rate:.1f}% of {total} generated tests")
    if failed:
        print("\n--- FAILURES (first 25) ---")
        for name, msg in failed[:25]:
            print(f"  {name}: {msg}")
    if errors:
        print("\n--- ERRORS (first 25) ---")
        for name, msg in errors[:25]:
            print(f"  {name}: {msg}")
    sys.exit(0 if not failed and not errors else 1)
